import {dataset} from '../game/tft-data';
defineProps<{advice?:ShoppingTactics}>();
const name=(id:string)=>dataset.characterById(id)?.display_name??'待更新';
const percent=(n:number)=>Math.round(n*100)+'%';
</script>
