      <details data-tactical-details><summary>换牌明细</summary><div v-for="group in [{label:'换上',units:choice.incoming},{label:'换下',units:choice.outgoing}]" :key="group.label" class="tactical-diff"><small>{{ group.label }}</small><span v-if="!group.units?.length">—</span><span v-for="unit in group.units" :key="unit.key" :title="name(unit.id)+' · '+unit.star+'星'+(unit.items.length?' · '+unit.items.map(id=>dataset.item(id)?.display_name??'装备待更新').join('、'):'')"><img :src="dataset.characterById(unit.id)?.image_path" :alt="name(unit.id)"/><small>{{ '★'.repeat(unit.star) }}</small></span></div><div v-for="upgrade in choice.upgraded" :key="upgrade.id" class="tactical-upgrade">{{ name(upgrade.id) }} {{ upgrade.before }} → {{ upgrade.after }} 星</div><div class="tactical-lineup"><span v-for="(id,i) in choice.onBoard" :key="id+i" :title="name(id)+' · '+choice.onBoardStars[i]+'星'"><img :src="dataset.characterById(id)?.image_path" :alt="name(id)"/><small>{{ '★'.repeat(choice.onBoardStars[i]) }}</small><span v-if="choice.onBoardItems?.[i]?.length" class="tactical-items"><img v-for="(item,j) in choice.onBoardItems[i]" :key="j" :src="dataset.item(item)?.image_path" :alt="dataset.item(item)?.display_name??'装备待更新'" :title="dataset.item(item)?.display_name??'装备待更新'"/></span></span></div></details>
    </article>
  </div>
  <p v-else>{{ advice?.reason??'等待金币与场上棋盘' }}</p>
</section></template>
